'use client'
import { createContext, useRef, useState, type Dispatch, type ReactNode, type SetStateAction } from 'react'

// Menu triggers in a row (shadcn's menubar): a Black strip in a hairline with the brand corner, 32px triggers in DM Sans
// Medium, each opening a panel of rows in the card's #171717 fill (MenubarMenu with MenubarItem, MenubarLabel and
// MenubarSeparator). One trigger is in the tab order; Left and Right move along the row, Down, Enter or Space open, and
// with a menu open Left and Right open the next one. While one is open, pointing at another trigger switches to it at
// once. Menus opened from the keyboard show without motion.
export interface MenubarEntry { key: string, el: () => HTMLElement | null, open: () => Promise<void> }
export interface MenubarContextValue {
  active: string | null
  setActive: Dispatch<SetStateAction<string | null>>
  focused: string | null
  setFocused: Dispatch<SetStateAction<string | null>>
  entries: MenubarEntry[]
  move: (from: string, step: number, open: boolean) => void
}
export const MenubarContext = createContext<MenubarContextValue | null>(null)
/** Closes the menu a row is in (refocusing its trigger). */
export const MenubarClose = createContext<() => void>(() => {})

export interface MenubarProps {
  /** The bar's name for assistive tech. */
  label: string
  /** MenubarMenu elements. */
  children?: ReactNode
}

export function Menubar({ label, children }: MenubarProps) {
  const [active, setActive] = useState<string | null>(null)
  const [focused, setFocused] = useState<string | null>(null)
  const entries = useRef<MenubarEntry[]>([]).current
  function move(from: string, step: number, open: boolean) {
    const at = entries.findIndex((e) => e.key === from)
    const next = entries[(at + step + entries.length) % entries.length]
    if (!next) return
    setFocused(next.key)
    next.el()?.focus()
    if (open) void next.open()
  }
  return (
    <MenubarContext.Provider value={{ active, setActive, focused, setFocused, entries, move }}>
      <div data-ds="menubar" role="menubar" aria-label={label} className="inline-flex items-center gap-1 rounded-control border border-edge bg-surface p-1">
        {children}
      </div>
    </MenubarContext.Provider>
  )
}

export default Menubar

'use client'
import { useContext, useEffect, useId, useRef, type KeyboardEvent, type MouseEvent, type ReactNode } from 'react'
import { MenubarClose, MenubarContext } from '@/components/ui/Menubar'
import { PopoverPanel } from '@/components/ui/PopoverPanel'
import { onMenuRows, usePopover } from '@/hooks/usePopover'

// One menu of a Menubar: its trigger and a panel of rows under it (MenubarItem, MenubarLabel, MenubarSeparator). The
// open trigger takes the #262626 fill; the others fill on hover.
export interface MenubarMenuProps {
  /** The trigger's label. */
  label: string
  /** The panel's width (a CSS length). */
  width?: string
  children?: ReactNode
}

export function MenubarMenu({ label, width = '224px', children }: MenubarMenuProps) {
  const bar = useContext(MenubarContext)!
  const key = useId()
  const pop = usePopover({ side: 'bottom', align: 'start', gap: 8 })

  async function open(focus: 'first' | 'last' | 'none' = 'first', keyboard = true) {
    await pop.show({ keyboard })
    if (focus === 'none') return pop.panel.current?.focus({ preventScroll: true })
    const rows = [...(pop.panel.current?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]
    ;(focus === 'last' ? rows.at(-1) : rows[0])?.focus()
  }
  const openRef = useRef(open)
  openRef.current = open
  useEffect(() => {
    const entry = { key, el: () => pop.anchor.current, open: () => openRef.current('first') }
    bar.entries.push(entry)
    bar.setFocused((f) => f ?? key)
    return () => { bar.entries.splice(bar.entries.indexOf(entry), 1) }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (pop.open) bar.setActive(key)
    else bar.setActive((a) => (a === key ? null : a))
  }, [pop.open]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (bar.active !== key && pop.open) pop.hide(false, true)
  }, [bar.active]) // eslint-disable-line react-hooks/exhaustive-deps

  function onClick(event: MouseEvent) {
    if (pop.open) return pop.hide(event.detail === 0, event.detail === 0)
    void open(event.detail === 0 ? 'first' : 'none', event.detail === 0)
  }
  function onEnter() {
    if (bar.active && bar.active !== key) void open('none', true)
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
      event.preventDefault()
      bar.move(key, event.key === 'ArrowRight' ? 1 : -1, false)
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      void open(event.key === 'ArrowDown' ? 'first' : 'last')
    }
  }
  function onPanelKey(event: KeyboardEvent) {
    if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
      event.preventDefault()
      pop.hide(false, true)
      bar.move(key, event.key === 'ArrowRight' ? 1 : -1, true)
      return
    }
    onMenuRows(event, pop.panel.current, pop.hide)
  }
  return (
    <MenubarClose.Provider value={() => pop.hide(true)}>
      <button
        data-ds="menubar-menu"
        ref={(el) => { pop.anchor.current = el }}
        type="button"
        role="menuitem"
        aria-haspopup="menu"
        aria-expanded={pop.open}
        tabIndex={bar.focused === key ? 0 : -1}
        className="inline-flex h-control-sm cursor-pointer items-center rounded-ds-sm px-3 type-ui-strong text-fg-soft -outline-offset-2 transition-[background-color,color] duration-150 ease-standard hover:not-aria-expanded:bg-action-ghost-hover hover:text-fg aria-expanded:bg-action-secondary aria-expanded:text-fg max-md:h-control-touch"
        onClick={onClick}
        onPointerEnter={onEnter}
        onFocus={() => bar.setFocused(key)}
        onKeyDown={onTriggerKey}
      >
        {label}
      </button>
      <PopoverPanel data-ds="menubar-menu" pop={pop} role="menu" aria-label={label} tabIndex={-1} className="flex flex-col p-1" style={{ width }} onKeyDown={onPanelKey}>
        {children}
      </PopoverPanel>
    </MenubarClose.Provider>
  )
}

export default MenubarMenu

'use client'
import { useContext, type PointerEvent, type ReactNode } from 'react'
import { Check } from 'lucide-react'
import { MenubarClose } from '@/components/ui/Menubar'
import { cn } from '@/lib/cn'

// One row of a MenubarMenu: 32px (44px on phones), DM Sans soft gray, the brand's small corner; the row under the
// pointer or focus takes the #262626 fill and White type. Put a 16px Lucide icon first, and a `shortcut` shows muted at
// the end. `checked` makes it a radio or checkbox row with a check (`role`). `danger` is a destructive row's red.
// Choosing it calls `onSelect` and closes the menu, unless `keepOpen`.
export interface MenubarItemProps {
  /** A key or keys, shown muted at the end. */
  shortcut?: string
  /** A destructive row (red). */
  danger?: boolean
  disabled?: boolean
  /** Keeps the menu open after it is chosen. */
  keepOpen?: boolean
  /** Checked, for a radio or checkbox row. */
  checked?: boolean
  role?: 'menuitem' | 'menuitemradio' | 'menuitemcheckbox'
  onSelect?: () => void
  className?: string
  children?: ReactNode
}

export function MenubarItem({ shortcut, danger, disabled, keepOpen, checked, role = 'menuitem', onSelect, className, children }: MenubarItemProps) {
  const close = useContext(MenubarClose)
  function choose() {
    onSelect?.()
    if (!keepOpen) close()
  }
  // The row under the pointer takes focus, so the pointer and the keys share one highlight.
  function onPointerMove(event: PointerEvent<HTMLButtonElement>) {
    if (!disabled && document.activeElement !== event.currentTarget) event.currentTarget.focus({ preventScroll: true })
  }
  return (
    <button
      data-ds="menubar-item"
      type="button"
      role={role}
      aria-checked={role === 'menuitem' ? undefined : !!checked}
      disabled={disabled}
      data-danger={danger || undefined}
      className={cn('flex h-control-sm w-full shrink-0 cursor-pointer items-center gap-3 rounded-ds-sm px-2 text-left type-ui text-fg-soft outline-none transition-[background-color,color] duration-150 ease-standard focus:bg-action-secondary focus:text-fg disabled:cursor-not-allowed disabled:text-fg-faint data-danger:text-fg-danger max-md:h-control-touch', className)}
      onPointerMove={onPointerMove}
      onClick={choose}
    >
      <span className="flex min-w-0 flex-1 items-center gap-3">{children}</span>
      {shortcut && <span className="type-caption text-fg-muted">{shortcut}</span>}
      {role !== 'menuitem' && checked && <Check size={16} strokeWidth={1.5} aria-hidden="true" className="shrink-0" />}
    </button>
  )
}

export default MenubarItem

import type { ReactNode } from 'react'

// A group's name in a MenubarMenu: DM Sans Medium in capitals at 6%, muted.
export interface MenubarLabelProps {
  children?: ReactNode
}

export function MenubarLabel({ children }: MenubarLabelProps) {
  return <p data-ds="menubar-label" className="px-2 pt-2 pb-1 type-label text-fg-muted">{children}</p>
}

export default MenubarLabel

// A hairline between groups of rows in a MenubarMenu.
export function MenubarSeparator() {
  return <div data-ds="menubar-separator" role="separator" className="-mx-1 my-1 h-px shrink-0 bg-edge" />
}

export default MenubarSeparator

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
